function TabDemo({ state }: { state: FixtureState }) {
    const initialTabs = state === "long"
        ? Array.from({ length: 8 }, (_, index) => ({ id: `candidate-${index + 1}`, label: `긴 이름의 후보자 ${index + 1} 상세 탭` }))
        : [{ id: "candidate-1", label: "김가상 후보자 상세" }, { id: "candidate-2", label: "긴 이름의 후보자 상세 탭" }];
    const [tabs, setTabs] = useState(initialTabs);
    const [active, setActive] = useState(initialTabs.at(-1)?.id ?? "list");
    const close = (value: string) => {
        const index = tabs.findIndex(tab => tab.id === value);
        if (index < 0) return;
        const next = tabs.filter(tab => tab.id !== value);
        setTabs(next);
        if (active === value) setActive(next[index - 1]?.id ?? next[index]?.id ?? "list");
    };
    return <div className="prism-demo-stack">
        <PrismTabs defaultValue="profile">
            <PrismTabsList aria-label="프로필 분류"><PrismTabsTrigger value="profile">프로필</PrismTabsTrigger><PrismTabsTrigger value="career" disabled={state === "disabled"}>경력</PrismTabsTrigger><PrismTabsTrigger value="memo" disabled>메모 준비 중</PrismTabsTrigger></PrismTabsList>
            <PrismTabsContent value="profile">기본 프로필</PrismTabsContent><PrismTabsContent value="career">주요 경력</PrismTabsContent><PrismTabsContent value="memo">메모 목록</PrismTabsContent>
        </PrismTabs>
        <PrismTabs value={active} onValueChange={setActive}>
            <PrismTabsList variant="fill" aria-label="열린 후보자 탭">
                <PrismTabsTrigger value="list">목록</PrismTabsTrigger>
                {tabs.map(tab => <PrismClosableTabTrigger key={tab.id} value={tab.id} label={tab.label} onClose={close} disabled={state === "disabled" && tab.id === "candidate-1"} />)}
            </PrismTabsList>
            <PrismTabsContent value="list">후보자 목록</PrismTabsContent>
            {tabs.map(tab => <PrismTabsContent key={tab.id} value={tab.id}>{tab.label}</PrismTabsContent>)}
        </PrismTabs>
    </div>;
}
